class Whycodes < Formula
  desc "Terminal coding agent written in Rust"
  homepage "https://why.codes"
  version "0.4.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.4.0/whycodes-aarch64-apple-darwin.tar.gz"
