      sha256 "d09f9f6fdf983f5804a0db8c0429b5851b387b1226b74297497c9ac2dff63408"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.4.0/whycodes-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "239ef0237c980be0f8fa640526f1237c11996468cedff21924723e96995afc3b"
    end
  end

  head do
    url "https://github.com/whycorporation/whycodes.git", branch: "main"
